from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import Json
from typing import Annotated, List
import pytest

app = FastAPI()

@app.post("/upload")
def upload(
    tags: Annotated[Json[List[str]], Form()]
):
    return {"tags": tags}

client = TestClient(app)

def test_json_list_form():
    # Client sends a JSON string in the form field 'tags'
    # In a real request, this would be sent as multipart/form-data or application/x-www-form-urlencoded
    # TestClient.post with data=... sends it as form-encoded
    response = client.post("/upload", data={"tags": '["abc", "def"]'})
    assert response.status_code == 200
    assert response.json() == {"tags": ["abc", "def"]}

if __name__ == "__main__":
    try:
        test_json_list_form()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
